// WEB-BOT-AUTH-1 (STD-3): Ultrastable's agents sign their outbound requests and verify inbound signed agents.
// Standards: HTTP Message Signatures (RFC 9421), Web Bot Auth profile (tag="web-bot-auth", Ed25519, key directory at
// /.well-known/http-message-signatures-directory, Signature-Agent header), JWK thumbprint key ids (RFC 7638).
// The signing key is generated by the Worker on first use and kept in the org database; nobody installs or pastes a key.
const ORIGIN = "https://ultrastable.io";
export const DIRECTORY_PATH = "/.well-known/http-message-signatures-directory";
export const DIRECTORY_TYPE = "application/http-message-signatures-directory+json";
const b64 = u8 => btoa(String.fromCharCode(...new Uint8Array(u8)));
const b64url = u8 => b64(u8).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
const unb64 = s => Uint8Array.from(atob(s), c => c.charCodeAt(0));
const unb64url = s => unb64(s.replace(/-/g, "+").replace(/_/g, "/").padEnd(Math.ceil(s.length / 4) * 4, "="));

export async function thumbprint(jwk) {  // RFC 7638 for OKP keys
  const canon = JSON.stringify({ crv: jwk.crv, kty: jwk.kty, x: jwk.x });
  return b64url(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(canon)));
}

async function loadKey(env) {
  await env.ORG.prepare("CREATE TABLE IF NOT EXISTS agent_keys (id TEXT PRIMARY KEY, purpose TEXT NOT NULL, jwk_private TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')))").run();
  const row = await env.ORG.prepare("SELECT jwk_private FROM agent_keys WHERE purpose = 'web-bot-auth' ORDER BY created_at DESC LIMIT 1").first();
  let priv = row && JSON.parse(row.jwk_private);
  if (!priv) {
    const kp = await crypto.subtle.generateKey("Ed25519", true, ["sign", "verify"]);
    priv = await crypto.subtle.exportKey("jwk", kp.privateKey); priv.key_ops = ["sign"]; delete priv.ext;
    const id = await thumbprint(priv);
    await env.ORG.prepare("INSERT OR IGNORE INTO agent_keys (id, purpose, jwk_private) VALUES (?, 'web-bot-auth', ?)").bind(id, JSON.stringify(priv)).run();
  }
  const pub = { kty: priv.kty, crv: priv.crv, x: priv.x };
  return { priv, pub, kid: await thumbprint(pub) };
}

export async function directory(env) {
  const k = await loadKey(env);
  return { keys: [{ ...k.pub, kid: k.kid }] };
}

export const sigParams = (components, created, expires, kid) => `(${components.map(c => `"${c}"`).join(" ")});created=${created};expires=${expires};keyid="${kid}";alg="ed25519";tag="web-bot-auth"`;
const base = (lines, params) => lines.map(([n, v]) => `"${n}": ${v}`).concat(`"@signature-params": ${params}`).join("\n");

// Returns the three headers to add to an outbound request to `url`.
export async function signRequest(env, url, now = Date.now(), ttlSeconds = 300) {
  const k = await loadKey(env), u = new URL(url);
  const created = Math.floor(now / 1000), expires = created + ttlSeconds, agentHdr = `"${ORIGIN}"`;
  const params = sigParams(["@authority", "signature-agent"], created, expires, k.kid);
  const key = await crypto.subtle.importKey("jwk", k.priv, "Ed25519", false, ["sign"]);
  const sig = await crypto.subtle.sign("Ed25519", key, new TextEncoder().encode(base([["@authority", u.host], ["signature-agent", agentHdr]], params)));
  return { "signature-agent": agentHdr, "signature-input": `sig1=${params}`, signature: `sig1=:${b64(sig)}:` };
}

// Verifies an inbound signed request. `getDirectory(agentOrigin)` returns the agent's key directory JSON (injected so tests and the Worker control fetching).
export async function verifyRequest(request, getDirectory, now = Date.now()) {
  const h = n => request.headers.get(n);
  const input = h("signature-input"), sigH = h("signature"), agent = h("signature-agent");
  if (!input || !sigH || !agent) return { ok: false, reason: "unsigned" };
  const m = /^sig1=(\(([^)]*)\))((?:;[^;]+)*)$/.exec(input.trim()); if (!m) return { ok: false, reason: "bad signature-input" };
  const params = m[1], comps = m[2].split(" ").filter(Boolean).map(s => s.replace(/"/g, ""));
  const meta = Object.fromEntries(m[3].split(";").filter(Boolean).map(p => { const i = p.indexOf(""); return [p.slice(0, i), p.slice(i + 1).replace(/^"|"$/g, "")]; }));
  if (meta.tag !== "web-bot-auth" || meta.alg !== "ed25519") return { ok: false, reason: "not a web-bot-auth ed25519 signature" };
  if (!comps.includes("@authority") || !comps.includes("signature-agent")) return { ok: false, reason: "components must cover @authority and signature-agent" };
  const t = Math.floor(now / 1000); if (!(Number(meta.created) <= t + 30) || !(Number(meta.expires) > t)) return { ok: false, reason: "signature outside its validity window" };
  const sm = /^sig1=:(.+):$/.exec(sigH.trim()); if (!sm) return { ok: false, reason: "bad signature" };
  const agentOrigin = agent.replace(/^"|"$/g, ""); if (!/^https:\/\/(?:[a-z0-9.-]+)(?::\d+)?$/i.test(agentOrigin)) return { ok: false, reason: "signature-agent must be an https origin" };
  const dir = await getDirectory(agentOrigin); const jwk = dir && (dir.keys || []).find(x => x.kid === meta.keyid);
  if (!jwk || await thumbprint(jwk) !== meta.keyid) return { ok: false, reason: "key not in the agent's directory" };
  const lines = comps.map(c => [c, c === "@authority" ? new URL(request.url).host : h(c)]); if (lines.some(([, v]) => v == null)) return { ok: false, reason: "covered header missing" };
  const key = await crypto.subtle.importKey("jwk", { kty: jwk.kty, crv: jwk.crv, x: jwk.x }, "Ed25519", false, ["verify"]);
  const good = await crypto.subtle.verify("Ed25519", key, unb64(sm[1]), new TextEncoder().encode(base(lines, params)));
  return good ? { ok: true, agent: agentOrigin, keyid: meta.keyid } : { ok: false, reason: "signature does not verify" };
}

// WBA-OUTBOUND-1: every outbound agent fetch carries a Web Bot Auth signature when the org key store is reachable; without it the request
// still goes out unsigned (signing never blocks a fetch). `f` is injected so tests and callers control the transport.
export async function signedFetch(env, url, init = {}, f = fetch, now = Date.now()) {
  const headers = new Headers(init.headers || {});
  if (env && env.ORG) {
    try { for (const [k, v] of Object.entries(await signRequest(env, String(url), now))) headers.set(k, v); } catch (e) { /* unsigned fallback */ }
  }
  return f(url, { ...init, headers });
}

export async function fetchDirectory(origin, f = fetch, env = null) {
  const init = { headers: { accept: DIRECTORY_TYPE }, signal: AbortSignal.timeout(4000) };
  const cache = directoryCache();
  return cache(origin, async (o) => {
    const r = env ? await signedFetch(env, o + DIRECTORY_PATH, init, f) : await f(o + DIRECTORY_PATH, init);
    if (!r.ok) return null;
    const d = await r.json().catch(() => null);
    return d && Array.isArray(d.keys) ? d : null;
  });
}

// WBA-OUTBOUND-1: peer key directories, cached per origin so a burst of signed requests from one agent costs one directory fetch.
// A found directory is kept `ttlMs`, a miss (null or error) `missTtlMs` so a dead peer is not refetched per request; concurrent lookups for
// one origin share one fetch; the oldest origin is dropped past `max`. Returns get(origin, fetcher) -> directory | null.
export function directoryCache({ ttlMs = 3600e3, missTtlMs = 300e3, max = 256, clock = () => Date.now() } = {}) {
  const hits = new Map(), inflight = new Map();
  const get = async (origin, fetcher) => {
    const t = clock(), e = hits.get(origin);
    if (e && t >= e.at && t - e.at < (e.dir ? ttlMs : missTtlMs)) return e.dir;
    if (inflight.has(origin)) return inflight.get(origin);
    const p = (async () => {
      let dir = null;
      try { dir = await fetcher(origin); } catch (err) { dir = null; }
      hits.delete(origin); hits.set(origin, { at: clock(), dir: dir || null });
      while (hits.size > max) hits.delete(hits.keys().next().value);
      return dir || null;
    })();
    inflight.set(origin, p);
    try { return await p; } finally { inflight.delete(origin); }
  };
  get.size = () => hits.size;
  get.clear = () => { hits.clear(); inflight.clear(); };
  return get;
}
